&lt;ActionGrid&gt;
  &lt;Settings&gt;
    &lt;Version&gt;5.28.0&lt;/Version&gt;
    &lt;Build&gt;5.28.314&lt;/Build&gt;
    &lt;CurrentContext&gt;ExportImport&lt;/CurrentContext&gt;
    &lt;ModuleId&gt;1497&lt;/ModuleId&gt;
    &lt;DataSource&gt;{&quot;DefinitionId&quot;:&quot;SqlQuery&quot;,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT\n    ROW_NUMBER() OVER\n    (\n        ORDER BY\n            CONVERT(date, bft.DataPlatii) DESC,\n            bft.CodSucursala,\n            bft.CodBanca,\n            bft.TipPlata\n    ) AS IdCentr,\n\n    bft.CodSucursala,\n\n    ISNULL\n    (\n        s.DenumireSucursala,\n        bft.CodSucursala\n    ) AS Sucursala,\n\n    bft.CodBanca,\n\n    bft.TipPlata,\n\n    bft.FileId,\n\n    CONVERT(date, bft.DataPlatii) AS DataPlatii,\n\n    COUNT(*) AS NumarFisiere,\n\n    SUM\n    (\n        ISNULL(bft.NumarSalariati, 0)\n    ) AS NumarSalariati,\n\n    SUM\n    (\n        ISNULL(bft.ValoareTotala, 0)\n    ) AS ValoareTotala,\n\n    bft.Status AS StatusCentralizare,\n\n    sc.Denumire AS DenumireStatus,\n\n    sc.Badge,\n\n    MIN(bft.CreatedDate) AS PrimaGenerare,\n\n    MAX(bft.CreatedDate) AS UltimaGenerare\n\nFROM app.BancaFisierTransfer bft\n\nLEFT JOIN app.Sucursala s\n    ON LTRIM(RTRIM(s.CodSucursala))\n       = LTRIM(RTRIM(bft.CodSucursala))\n\nLEFT JOIN app.StatusCalcul sc\n    ON sc.Id = bft.Status\n\nWHERE bft.Status IN (8, 10)\n\n  AND bft.FileId IS NOT NULL\n\n  AND bft.Luna = @Luna\n\n  AND bft.Anul = @Anul\n\nGROUP BY\n    bft.CodSucursala,\n    s.DenumireSucursala,\n    bft.CodBanca,\n    bft.TipPlata,\n    bft.FileId,\n    bft.Status,\n    sc.Denumire,\n    sc.Badge,\n    CONVERT(date, bft.DataPlatii)\n\nORDER BY\n    CONVERT(date, bft.DataPlatii) DESC,\n    bft.CodSucursala,\n    bft.CodBanca,\n    bft.TipPlata;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;IdColumn&quot;:&quot;IdCentr&quot;,&quot;SqlQueryColumns&quot;:&quot;&quot;,&quot;SqlQueryInsert&quot;:&quot;&quot;,&quot;SqlQueryUpdate&quot;:&quot;&quot;,&quot;SqlQueryDelete&quot;:&quot;&quot;,&quot;AddUrl&quot;:&quot;&quot;,&quot;EditUrl&quot;:&quot;&quot;,&quot;ViewUrl&quot;:&quot;&quot;},&quot;Fields&quot;:[{&quot;Title&quot;:&quot;IdCentr&quot;,&quot;Name&quot;:&quot;IdCentr&quot;,&quot;TypeStr&quot;:&quot;System.Int64, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodSucursala&quot;,&quot;Name&quot;:&quot;CodSucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;Sucursala&quot;,&quot;Name&quot;:&quot;Sucursala&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;CodBanca&quot;,&quot;Name&quot;:&quot;CodBanca&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;TipPlata&quot;,&quot;Name&quot;:&quot;TipPlata&quot;,&quot;TypeStr&quot;:&quot;System.String, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;FileId&quot;,&quot;Name&quot;:&quot;FileId&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;DataPlatii&quot;,&quot;Name&quot;:&quot;DataPlatii&quot;,&quot;TypeStr&quot;:&quot;System.DateTime, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumarFisiere&quot;,&quot;Name&quot;:&quot;NumarFisiere&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;NumarSalariati&quot;,&quot;Name&quot;:&quot;NumarSalariati&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089&quot;,&quot;CanBeSearchable&quot;:true,&quot;CanBeSortable&quot;:true,&quot;CanBeFilterable&quot;:true,&quot;SupportsUpdate&quot;:false,&quot;IsNullable&quot;:true,&quot;DefaultValue&quot;:null},{&quot;Title&quot;:&quot;ValoareTotala&quot;,&quot;Name&quot;:&quot;ValoareTotala&quot;,&quot;TypeStr&quot;:&quot;System.Int32, mscorlib, Version=4.0.0